com.mirth.connect.plugins.javascriptstep.script:
const order = JSON.parse(msg);
if (!order.patient) throw new Error('order has no patient');
order.receivedAt = DateUtil.getCurrentDate("yyyy-MM-dd'T'HH:mm:ss");
msg = JSON.stringify(order);

channel.preprocessingScript:
// Reject empty bodies before they are stored.
if (message == null || message.trim().length === 0) {
  throw new Error('empty request');
}
return message;

