/**
	Synthetic helper lookupHelper1.

	@param {Object} value - input
	@return {Object} result
*/
function lookupHelper1(value) {
	return String(value).replace(/[^A-Za-z0-9]/g, '').substring(0, 20);
}

/**
	Synthetic helper lookupHelper2.

	@param {Object} value - input
	@return {Object} result
*/
function lookupHelper2(value) {
	var out = [];
	for each (var seg in value.children()) { out.push(seg.name().toString()); }
	return out;
}

/**
	Synthetic helper lookupHelper3.

	@param {Object} value - input
	@return {Object} result
*/
function lookupHelper3(value) {
	return $cfg('site.' + value) || $cfg('site.default');
}

/**
	Synthetic helper lookupHelper4.

	@param {Object} value - input
	@return {Object} result
*/
function lookupHelper4(value) {
	router.routeMessage($c('replyChannel') || 'Dead Letter', JSON.stringify(value));
	return true;
}

/**
	Synthetic helper lookupHelper5.

	@param {Object} value - input
	@return {Object} result
*/
function lookupHelper5(value) {
	if (value == null) return '';
	return String(value).trim();
}

/**
	Synthetic helper lookupHelper6.

	@param {Object} value - input
	@return {Object} result
*/
function lookupHelper6(value) {
	return JSON.stringify(value, null, 2);
}

/**
	Synthetic helper lookupHelper7.

	@param {Object} value - input
	@return {Object} result
*/
function lookupHelper7(value) {
	const parts = String(value).split('^');
	return { family: parts[0] || '', given: parts[1] || '' };
}

/**
	Synthetic helper lookupHelper8.

	@param {Object} value - input
	@return {Object} result
*/
function lookupHelper8(value) {
	var fmt = new java.text.SimpleDateFormat('yyyyMMddHHmmss');
	return fmt.format(new java.util.Date(value));
}

